// SourceMetadata returns fixed index metadata for already returned sources.
// It copies no authority text and performs no passage traversal.
func (l *Lexical) SourceMetadata(sourceIDs []string) map[string]coverage.Source {
	l.mu.RLock()
	defer l.mu.RUnlock()
	result := make(map[string]coverage.Source, len(sourceIDs))
	for _, sourceID := range sourceIDs {
		documentID, exists := l.docs[sourceID]
		if !exists || int(documentID) >= len(l.documents) { continue }
		document := l.documents[documentID]
		if document == nil || document.information.ID != sourceID { continue }
		eligible := 0.0
		if document.deep { eligible = 1 }
		result[sourceID] = coverage.Source{PassageScore: eligible, Diversity: document.diversity}
	}
	return result
}

